  const [trade, industry, product, purpose] = pick(r, TRADES);
  let company = `${pick(r, PLACES)} ${trade} Pte Ltd`;
  for (let i = 0; USED.has(company) && i < 20; i++) company = `${pick(r, PLACES)} ${trade} Pte Ltd`;
  USED.add(company);
